<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';

type Page = 'inbox' | 'temporary' | 'accounts' | 'tasks' | 'settings';
type Mailbox = { id:string; address:string; status:'active'|'expired'|'deleting'; createdAt:number; expiresAt:number };
type Email = { id:string; mailboxId:string|null; fromAddress:string; subject:string; snippet:string; receivedAt:number; localIsRead:number; source:string };
type Detail = Email & { text:string; otpCandidates:string[]; bodyTruncated:boolean; hasHtml:boolean; attachments:Array<{id:string;filename:string;size:number;skippedReason:string|null}> };
type Account = { id:string;provider:string;connectionType:string;emailAddress:string;authStatus:string;syncStatus:string;imapProvider?:string;folders?:string[]|string };
type Job = {id:string;kind:string;targetId:string;targetLabel:string;status:string;attempts:number;maxAttempts:number;availableAt:number;errorCode:string|null;createdAt:number;updatedAt:number};
type GmailSetup = {configured:boolean;missingSecrets:string[];redirectUri:string|null};
const pages: {id:Page;label:string;icon:string}[]=[{id:'inbox',label:'统一收件箱',icon:'▤'},{id:'temporary',label:'临时邮箱',icon:'◷'},{id:'accounts',label:'邮箱连接',icon:'⊞'},{id:'tasks',label:'任务中心',icon:'◷'},{id:'settings',label:'偏好设置',icon:'⚙'}];
const page=ref<Page>('inbox'), mailboxes=ref<Mailbox[]>([]), emails=ref<Email[]>([]), selectedMailbox=ref(''), selectedEmail=ref<Detail|null>(null), accounts=ref<Account[]>([]),jobs=ref<Job[]>([]),gmailSetup=ref<GmailSetup>({configured:false,missingSecrets:[],redirectUri:null});
const busy=ref(false), loading=ref(true), error=ref(''), notice=ref(''), health=ref('checking');
const search=ref(''), sourceFilter=ref('all'), unreadFilter=ref('all'), nextCursor=ref<string|null>(null), loadingMore=ref(false);
const showOtp=ref(false), bodyMode=ref<'text'|'html'>('text');
const preferences=ref({ttl:60,refreshSeconds:20,maskOtp:true,theme:'light'});
const forwardedSettings=ref({provider:'qq',emailAddress:'',appPassword:'',folders:'INBOX'});
const visibleEmails=computed(()=>selectedMailbox.value?emails.value.filter(e=>e.mailboxId===selectedMailbox.value):emails.value);
const unreadCount=computed(()=>visibleEmails.value.filter(e=>!e.localIsRead).length);
const unreadTotal=computed(()=>emails.value.filter(e=>!e.localIsRead).length);
const activeMailboxes=computed(()=>mailboxes.value.filter(box=>box.status==='active').length);
let refreshTimer:number|undefined, searchTimer:number|undefined, inboxRequestId=0;
async function api<T>(path:string, init:RequestInit={}):Promise<T>{const headers=new Headers(init.headers);if(init.body)headers.set('Content-Type','application/json');const response=await fetch(path,{...init,headers});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data?.error?.message??`请求失败 (${response.status})`);return data as T;}
function emailListUrl(cursor?:string){const params=new URLSearchParams({limit:'100'});if(selectedMailbox.value)params.set('mailboxId',selectedMailbox.value);if(sourceFilter.value!=='all')params.set('source',sourceFilter.value);if(unreadFilter.value!=='all')params.set('unread',unreadFilter.value);if(search.value.trim())params.set('q',search.value.trim());if(cursor)params.set('cursor',cursor);return `/api/v1/emails?${params}`;}
async function reload(){const requestId=++inboxRequestId;loadingMore.value=false;error.value='';try{const [m,e,a,j,g]=await Promise.all([api<{mailboxes:Mailbox[]}>('/api/v1/mailboxes'),api<{emails:Email[];nextCursor:string|null}>(emailListUrl()),api<{accounts:Account[]}>('/api/v1/accounts'),api<{jobs:Job[]}>('/api/v1/jobs?limit=50'),api<GmailSetup>('/api/v1/accounts/gmail/status')]);if(requestId!==inboxRequestId)return;mailboxes.value=m.mailboxes;emails.value=e.emails;nextCursor.value=e.nextCursor;accounts.value=a.accounts;jobs.value=j.jobs;gmailSetup.value=g;const forwarded=a.accounts.find(account=>account.connectionType==='forwarded_imap');if(forwarded){forwardedSettings.value.emailAddress=forwarded.emailAddress;forwardedSettings.value.provider=forwarded.imapProvider??'qq';if(forwarded.folders){try{const folders=Array.isArray(forwarded.folders)?forwarded.folders:JSON.parse(forwarded.folders);if(Array.isArray(folders))forwardedSettings.value.folders=folders.join('\n');}catch{/* Keep the default folder when the saved folder list is malformed. */}}}health.value='ready';}catch(e){if(requestId!==inboxRequestId)return;health.value='error';error.value=e instanceof Error?e.message:'无法连接服务';}finally{if(requestId===inboxRequestId)loading.value=false;}}
async function loadMore(){if(!nextCursor.value||loadingMore.value)return;const requestId=++inboxRequestId;loadingMore.value=true;error.value='';try{const result=await api<{emails:Email[];nextCursor:string|null}>(emailListUrl(nextCursor.value));if(requestId!==inboxRequestId)return;emails.value=[...emails.value,...result.emails];nextCursor.value=result.nextCursor;}catch(e){if(requestId===inboxRequestId)error.value=e instanceof Error?e.message:'无法读取更多邮件';}finally{if(requestId===inboxRequestId)loadingMore.value=false;}}
function searchChanged(){if(searchTimer)clearTimeout(searchTimer);searchTimer=window.setTimeout(()=>void reload(),300);}
function filtersChanged(){void reload();}
function go(next:Page){page.value=next;selectedEmail.value=null;if(next==='inbox'){selectedMailbox.value='';void reload();}}
async function createMailbox(){busy.value=true;error.value='';notice.value='';try{const result=await api<{mailbox:Mailbox}>('/api/v1/mailboxes',{method:'POST',headers:{Origin:location.origin,'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({ttlMinutes:preferences.value.ttl})});selectedMailbox.value=result.mailbox.id;page.value='inbox';await reload();notice.value='临时邮箱已创建';}catch(e){error.value=e instanceof Error?e.message:'创建失败';}finally{busy.value=false;}}
async function connectGmail(){busy.value=true;error.value='';try{const result=await api<{authorizationUrl:string}>('/api/v1/accounts/gmail/connect',{method:'POST',headers:{Origin:location.origin},body:'{}'});location.assign(result.authorizationUrl);}catch(e){error.value=e instanceof Error?e.message:'无法连接 Gmail';busy.value=false;}}
async function saveForwardedSettings(){busy.value=true;error.value='';try{const result=await api<{account:Account}>('/api/v1/accounts/forwarded-imap',{method:'POST',headers:{Origin:location.origin},body:JSON.stringify({provider:forwardedSettings.value.provider,emailAddress:forwardedSettings.value.emailAddress,appPassword:forwardedSettings.value.appPassword,folders:forwardedSettings.value.folders.split(/[\n,]/).map(value=>value.trim()).filter(Boolean)})});forwardedSettings.value.appPassword='';await reload();notice.value=`转发汇总邮箱已连接：${result.account.emailAddress}，首次同步任务已排队`;}catch(e){error.value=e instanceof Error?e.message:'无法连接汇总邮箱';}finally{busy.value=false;}}
async function syncGmail(account:Account){busy.value=true;error.value='';try{const result=await api<{status:string}>(`/api/v1/accounts/${account.id}/sync`,{method:'POST',headers:{Origin:location.origin}});notice.value=result.status==='running'?'邮箱同步正在运行':'邮箱同步任务已排队';await reload();}catch(e){error.value=e instanceof Error?e.message:'无法启动同步';}finally{busy.value=false;}}
async function retryJob(job:Job){busy.value=true;error.value='';try{await api(`/api/v1/jobs/${job.id}/retry`,{method:'POST',headers:{Origin:location.origin}});await reload();notice.value='任务已重新排队';}catch(e){error.value=e instanceof Error?e.message:'无法重试任务';}finally{busy.value=false;}}
async function renewMailbox(box:Mailbox){busy.value=true;error.value='';try{await api(`/api/v1/mailboxes/${box.id}/renew`,{method:'POST',headers:{Origin:location.origin},body:JSON.stringify({ttlMinutes:60})});await reload();notice.value='邮箱有效期已延长';}catch(e){error.value=e instanceof Error?e.message:'续期失败';}finally{busy.value=false;}}
async function deleteMailbox(box:Mailbox){busy.value=true;error.value='';try{await api(`/api/v1/mailboxes/${box.id}`,{method:'DELETE',headers:{Origin:location.origin}});selectedMailbox.value='';selectedEmail.value=null;await reload();notice.value='邮箱已停用，清理任务已排队';}catch(e){error.value=e instanceof Error?e.message:'删除失败';}finally{busy.value=false;}}
async function openEmail(item:Email){error.value='';try{const result=await api<{email:Detail}>(`/api/v1/emails/${item.id}`);selectedEmail.value=result.email;showOtp.value=!preferences.value.maskOtp;bodyMode.value='text';if(!item.localIsRead){await api(`/api/v1/emails/${item.id}`,{method:'PATCH',headers:{Origin:location.origin},body:JSON.stringify({localIsRead:true})});item.localIsRead=1;if(unreadFilter.value==='true')emails.value=emails.value.filter(email=>email.id!==item.id);}}catch(e){error.value=e instanceof Error?e.message:'无法打开邮件';}}
function copyValue(value:string){navigator.clipboard.writeText(value).then(()=>notice.value='内容已复制').catch(()=>error.value='复制失败，请手动复制');}
function expiry(value:number){const delta=Math.max(0,value-Date.now());if(delta===0)return'已过期';const mins=Math.ceil(delta/60000);return mins<60?`${mins} 分钟后过期`:`${Math.floor(mins/60)} 小时 ${mins%60} 分钟后过期`;}
function date(value:number){return new Date(value).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function savePreferences(){localStorage.setItem('mailhub-ui-preferences',JSON.stringify(preferences.value));updateRefreshTimer();notice.value='偏好设置已保存';}
function loadPreferences(){try{const stored=localStorage.getItem('mailhub-ui-preferences');if(stored)preferences.value={...preferences.value,...JSON.parse(stored)};}catch{/* Keep safe defaults when local settings are unreadable. */}}
function updateRefreshTimer(){if(refreshTimer)clearInterval(refreshTimer);refreshTimer=window.setInterval(()=>void reload(),preferences.value.refreshSeconds*1000);}
watch(()=>preferences.value.theme,value=>{document.documentElement.dataset.theme=value;});
onMounted(async()=>{loadPreferences();const result=new URLSearchParams(location.search).get('gmail');if(result){page.value='accounts';notice.value=result==='connected'?'Gmail 已连接，可以启动首次同步。':result==='cancelled'?'已取消 Gmail 授权。':'Gmail 授权未完成。';history.replaceState({},'',location.pathname);}await reload();updateRefreshTimer();});
onUnmounted(()=>{if(refreshTimer)clearInterval(refreshTimer);if(searchTimer)clearTimeout(searchTimer);});
</script>

<template>
  <div class="app-shell">
    <aside class="sidebar">
      <div class="brand-block"><div class="brand"><span class="brand-icon">✉</span><span>MailHub</span><small>BETA</small></div><div class="brand-sub">PERSONAL INBOX</div></div>
      <nav class="main-nav" aria-label="主导航"><button v-for="item in pages" :key="item.id" class="nav-item" :class="{active:page===item.id}" @click="go(item.id)"><span class="nav-icon">{{ item.icon }}</span>{{ item.label }}<small v-if="item.id==='inbox'&&unreadTotal">{{ unreadTotal }}</small></button></nav>
      <section class="side-private"><div class="section-label">YOUR PRIVATE SPACE</div><div class="side-card"><strong><i></i>只属于你的收件箱</strong><p>临时地址与个人邮箱<br>分开接入，统一阅读。</p><small>只读连接 · 私密访问</small></div></section>
      <div class="side-bottom"><div class="service-line"><i :class="health"></i>{{ health==='ready'?'服务已连接':health==='error'?'连接异常':'正在检查' }}</div><div class="owner"><span>M</span><div>个人工作台<small>单人所有者 · Cloudflare</small></div></div></div>
    </aside>

    <main class="main-area">
      <header class="topbar"><div class="breadcrumbs">工作空间 <span>/</span> <strong>{{ pages.find(item=>item.id===page)?.label }}</strong></div><div class="top-actions"><span class="secure-label">◆ 私有空间</span><button class="refresh-button" :disabled="loading" @click="reload">↻ 刷新</button></div></header>
      <div v-if="error" class="alert error-alert"><span>{{ error }}</span><button @click="error=''">×</button></div><div v-if="notice" class="alert success-alert"><span>{{ notice }}</span><button @click="notice=''">×</button></div>

      <template v-if="page==='inbox'">
        <section class="page-title"><div><p class="eyebrow">MAIL WORKSPACE</p><h1>把重要的邮件，放在一起。</h1><p>统一管理临时地址与个人邮箱，让每一次收件都清晰可见。</p></div><div class="title-actions"><button class="button" @click="reload">↻ 刷新列表</button><button class="button primary" :disabled="busy" @click="createMailbox">＋ 创建临时邮箱</button></div></section>
        <section class="metrics"><article class="metric"><div><span>当前可用邮件</span><strong>{{ visibleEmails.length }}<small> 封</small></strong></div><i>✉</i></article><article class="metric"><div><span>待阅读 · 本地状态</span><strong>{{ unreadCount }}</strong></div><i>◎</i></article><article class="metric"><div><span>活跃临时邮箱</span><strong>{{ activeMailboxes }}</strong></div><i>◷</i></article></section>
        <section class="inbox-workspace" :class="{'mobile-detail-open':selectedEmail}">
          <div class="inbox-list"><div class="list-tools"><label class="search-box"><span>⌕</span><input v-model="search" type="search" maxlength="120" placeholder="搜索主题、发件人…" aria-label="搜索主题或发件人" @input="searchChanged"></label><div class="filters"><button v-for="filter in [{id:'all',label:'全部来源'},{id:'temporary',label:'临时邮箱'},{id:'gmail',label:'Gmail'}]" :key="filter.id" class="chip" :class="{active:sourceFilter===filter.id}" @click="sourceFilter=filter.id;filtersChanged()">{{ filter.label }}</button><select v-model="unreadFilter" aria-label="按已读状态筛选" @change="filtersChanged"><option value="all">全部状态</option><option value="true">仅未读</option><option value="false">已读</option></select></div></div>
            <div class="list-caption"><span>{{ visibleEmails.length }} 封邮件</span><span>最新优先</span></div>
            <div v-if="loading" class="empty-state">正在读取邮件…</div><div v-else-if="!visibleEmails.length" class="empty-state"><b>✉</b><strong>{{ search||sourceFilter!=='all'||unreadFilter!=='all'?'没有符合条件的邮件':'还没有邮件' }}</strong><span>{{ search||sourceFilter!=='all'||unreadFilter!=='all'?'试试调整搜索词或筛选条件。':'创建临时邮箱并将地址提供给发件人。' }}</span></div>
            <button v-for="item in visibleEmails" :key="item.id" class="email-row" :class="{unread:!item.localIsRead,selected:selectedEmail?.id===item.id}" @click="openEmail(item)"><div class="email-top"><strong><i class="unread-dot"></i>{{ item.fromAddress||'未知发件人' }}</strong><time>{{ date(item.receivedAt) }}</time></div><div class="email-subject">{{ item.subject||'（无主题）' }}</div><div class="email-snippet">{{ item.snippet }}</div><span class="source-badge" :class="item.source">{{ item.source==='temporary'?'临时邮箱':'Gmail' }}</span></button>
            <div v-if="nextCursor" class="load-more"><button class="button" :disabled="loadingMore" @click="loadMore">{{ loadingMore?'正在加载…':'加载更多' }}</button></div>
          </div>
          <section v-if="selectedEmail" class="email-detail"><div class="detail-toolbar"><button class="back-button" @click="selectedEmail=null">‹ 返回列表</button><span class="source-badge" :class="selectedEmail.source">{{ selectedEmail.source==='temporary'?'临时邮箱':'Gmail' }}</span><time>{{ date(selectedEmail.receivedAt) }}</time></div><article class="detail-content"><h2>{{ selectedEmail.subject||'（无主题）' }}</h2><div class="sender"><span class="sender-avatar">{{ (selectedEmail.fromAddress||'?').slice(0,1).toUpperCase() }}</span><div><strong>{{ selectedEmail.fromAddress||'未知发件人' }}</strong><small>收件时间 {{ date(selectedEmail.receivedAt) }}</small></div></div>
              <div v-if="selectedEmail.otpCandidates.length" class="otp-card"><div class="otp-heading"><div><strong>识别到的验证码</strong><small>候选值，请核对原文</small></div><button class="text-button" @click="showOtp=!showOtp">{{ showOtp?'隐藏':'显示' }}</button></div><div class="otp-values"><button v-for="otp in selectedEmail.otpCandidates" :key="otp" class="otp-code" @click="copyValue(otp)">{{ showOtp?otp:'••••••' }} <small>复制</small></button></div></div>
              <p v-if="selectedEmail.bodyTruncated" class="truncated-note">正文超过显示上限，已截断。</p><div class="body-tabs"><button :class="{active:bodyMode==='text'}" @click="bodyMode='text'">纯文本</button><button :class="{active:bodyMode==='html'}" :disabled="!selectedEmail.hasHtml" @click="bodyMode='html'">隔离 HTML</button></div><div v-if="bodyMode==='text'" class="mail-body">{{ selectedEmail.text||selectedEmail.snippet||'此邮件没有纯文本正文。' }}</div><iframe v-else class="html-frame" :src="`/api/v1/emails/${selectedEmail.id}/html`" sandbox="" referrerpolicy="no-referrer" title="经过净化的邮件 HTML"></iframe>
              <section v-if="selectedEmail.attachments.length" class="attachment-list"><h3>附件</h3><template v-for="item in selectedEmail.attachments" :key="item.id"><a v-if="!item.skippedReason" :href="`/api/v1/emails/${selectedEmail.id}/attachments/${item.id}`" class="attachment">↧ {{ item.filename }} <small>{{ Math.ceil(item.size/1024) }} KB</small></a><div v-else class="attachment skipped">{{ item.filename }} <small>未保存：{{ item.skippedReason }}</small></div></template><p>附件未经过病毒扫描，请谨慎打开。</p></section>
          </article></section>
          <section v-else class="detail-placeholder"><div>✉</div><strong>选择一封邮件开始阅读</strong><span>邮件详情会显示在这里</span></section>
        </section><footer class="page-note">MailHub / 安静、私密、有序的邮箱工作台 <span>邮件内容保存在你的 Cloudflare 账户中 · 临时邮箱到期后立即停止访问</span></footer>
      </template>

      <template v-else-if="page==='temporary'"><section class="page-title"><div><p class="eyebrow">TEMPORARY ADDRESSES</p><h1>短暂的地址，完整的掌控。</h1><p>创建仅属于你的临时邮箱，到期后立即停止读取。</p></div><button class="button primary" :disabled="busy" @click="createMailbox">＋ 创建临时邮箱</button></section><div class="info-banner">临时邮箱不会提供匿名公开读取链接。过期后立即禁读；删除会停用地址并排队清理关联邮件。</div><section class="cards"><article v-for="box in mailboxes" :key="box.id" class="card mailbox-card"><div class="card-head"><span class="pill-icon">◷</span><span class="status-badge" :class="box.status">{{ box.status==='active'?'接收中':box.status==='deleting'?'清理中':'已到期' }}</span></div><div class="email-address">{{ box.address }}</div><div class="progress"><i :style="{width:box.status==='active'?`${Math.max(0,Math.min(100,(box.expiresAt-Date.now())/(box.expiresAt-box.createdAt)*100))}%`:'0%'}"></i></div><div class="key-value"><span>剩余时间</span><b>{{ box.status==='active'?expiry(box.expiresAt):'不可读取' }}</b></div><div class="key-value"><span>到期时间</span><b>{{ date(box.expiresAt) }}</b></div><div class="key-value"><span>关联邮件</span><b>{{ emails.filter(email=>email.mailboxId===box.id).length }} 封（已加载）</b></div><div class="card-actions"><button class="button small" @click="copyValue(box.address)">复制地址</button><button class="button small" :disabled="busy||box.status!=='active'" @click="renewMailbox(box)">延长 60 分钟</button><button class="button small danger" :disabled="busy||box.status==='deleting'" @click="deleteMailbox(box)">删除</button></div></article><article v-if="!mailboxes.length" class="card empty-card"><div class="pill-icon">＋</div><h3>还没有临时邮箱</h3><p>创建一个私有地址来接收邮件。</p><button class="button primary" :disabled="busy" @click="createMailbox">创建临时邮箱</button></article></section></template>

      <template v-else-if="page==='accounts'"><section class="page-title"><div><p class="eyebrow">CONNECTED ACCOUNTS</p><h1>连接你的邮箱，不交出控制权。</h1><p>支持官方只读授权，或读取已转发邮件的汇总邮箱。</p></div></section><div v-if="!gmailSetup.configured&&!accounts.some(account=>account.connectionType==='forwarded_imap')" class="info-banner config-warning">Google OAuth 尚未配置。转发汇总邮箱可直接在「偏好设置」中连接。Google OAuth 配置缺少：{{ gmailSetup.missingSecrets.join(', ') }}<br>授权回调地址：<code>{{ gmailSetup.redirectUri||'https://ear1.de5.net/oauth/gmail/callback' }}</code>。</div><section class="cards"><article v-for="account in accounts" :key="account.id" class="card account-card"><div class="card-head"><div class="provider-title"><span class="provider-icon">{{ account.connectionType==='forwarded_imap'?(account.imapProvider==='qq'?'Q':'M'):'G' }}</span><div><h3>{{ account.connectionType==='forwarded_imap'?'转发汇总邮箱': 'Google Gmail' }}</h3><small>{{ account.connectionType==='forwarded_imap'?`${account.imapProvider==='qq'?'QQ Mail':'Gmail'} · IMAP`:'官方 OAuth · 只读连接' }}</small></div></div><span class="status-badge" :class="account.authStatus==='connected'?'active':'expired'">{{ account.authStatus==='connected'?'已连接':account.authStatus }}</span></div><div class="email-address">{{ account.emailAddress }}</div><div class="key-value"><span>同步状态</span><b>{{ account.syncStatus }}</b></div><div class="key-value"><span>{{ account.connectionType==='forwarded_imap'?'同步方式':'Gmail 原邮件' }}</span><b>{{ account.connectionType==='forwarded_imap'?'读取转发后的汇总邮件':'本地操作不会修改' }}</b></div><div class="card-actions"><button v-if="account.authStatus==='connected'" class="button primary" :disabled="busy" @click="syncGmail(account)">立即同步</button><button v-else class="button primary" :disabled="busy||!gmailSetup.configured" @click="connectGmail">重新授权</button><span v-if="account.authStatus==='connected'" class="muted">{{ account.connectionType==='forwarded_imap'?'每分钟检查新邮件':'首次同步范围由服务端控制' }}</span></div></article><article v-if="!accounts.some(account=>account.connectionType!=='forwarded_imap')" class="card empty-card"><span class="provider-icon">G</span><h3>连接 Gmail</h3><p>OAuth 配置完成后，可将 Gmail 邮件同步到统一收件箱。</p><button class="button primary" :disabled="busy||!gmailSetup.configured" @click="connectGmail">连接账号</button></article><article class="card outlook-card"><div class="card-head"><div class="provider-title"><span class="provider-icon outlook">O</span><div><h3>Microsoft Outlook</h3><small>Microsoft Graph</small></div></div><span class="status-badge">后续阶段</span></div><p>当前版本尚未开放 Outlook 接入。</p><button class="button" disabled>暂不开放</button></article></section></template>

      <template v-else-if="page==='tasks'"><section class="page-title"><div><p class="eyebrow">BACKGROUND ACTIVITY</p><h1>任务中心</h1><p>查看服务端同步与邮箱清理任务，失败任务可以重新排队。</p></div><button class="button" @click="reload">↻ 更新状态</button></section><section class="card task-card"><div class="card-head"><h2>最近任务</h2><span class="status-badge">最近 {{ jobs.length }} 条</span></div><div v-for="job in jobs" :key="job.id" class="task-row"><div class="task-info"><strong>{{ job.kind==='sync'?'Gmail 增量同步':job.kind==='cleanup_mailbox'?'临时邮箱数据清理':'后台任务' }}</strong><small>{{ job.targetLabel||job.targetId }} · {{ date(job.updatedAt) }} · 尝试 {{ job.attempts }}/{{ job.maxAttempts }}</small><small v-if="job.errorCode" class="task-error">{{ job.errorCode }}</small></div><div class="task-status"><span class="status-badge" :class="{active:['pending','running'].includes(job.status),deleting:job.status==='dead',expired:job.status==='retry_wait'}">{{ ({pending:'排队中',running:'执行中',retry_wait:'等待重试',succeeded:'已完成',dead:'失败',cancelled:'已取消'} as Record<string,string>)[job.status]||job.status }}</span><button v-if="['dead','retry_wait'].includes(job.status)" class="button small" :disabled="busy" @click="retryJob(job)">重试</button></div></div><div v-if="!jobs.length" class="empty-state task-empty"><b>✓</b><strong>暂时没有后台任务</strong><span>发起 Gmail 同步或删除临时邮箱后，任务会出现在这里。</span></div><div class="task-note">最多展示最近 50 条任务。失败重试会重新排队；Gmail 账号需先处于已授权状态。</div></section></template>

      <template v-else><section class="page-title"><div><p class="eyebrow">PREFERENCES</p><h1>让工作台，配合你的节奏。</h1><p>这些偏好保存在当前浏览器，不会影响邮箱内容或 Cloudflare 数据。</p></div></section><section class="card imap-settings-card">
  <div class="card-head">
    <div><h2>转发汇总邮箱（IMAP）</h2><p>如果你已把几个邮箱转发到一个收件箱，在这里填写中转邮箱的 IMAP 账号。</p></div>
    <span class="status-badge" :class="accounts.some(account=>account.connectionType==='forwarded_imap'&&account.authStatus==='connected')?'active':''">{{ accounts.some(account=>account.connectionType==='forwarded_imap'&&account.authStatus==='connected')?'已连接':'未连接' }}</span>
  </div>
  <form @submit.prevent="saveForwardedSettings">
    <label class="setting-row"><span><strong>中转邮箱类型</strong><small>选择为转发邮件提供 IMAP 服务的邮箱。</small></span><select v-model="forwardedSettings.provider"><option value="qq">QQ 邮箱</option><option value="gmail">Gmail</option></select></label>
    <label class="setting-row"><span><strong>中转邮箱地址</strong><small>用于登录 IMAP 服务器。</small></span><input v-model="forwardedSettings.emailAddress" required type="email" autocomplete="username" placeholder="name@example.com"></label>
    <label class="setting-row"><span><strong>IMAP 授权码</strong><small>填写邮箱提供商生成的应用专用码，不是邮箱登录密码。更新配置时需要重新填写。</small></span><input v-model="forwardedSettings.appPassword" required type="password" autocomplete="new-password" placeholder="邮箱授权码"></label>
    <label class="setting-row folder-setting"><span><strong>同步文件夹</strong><small>每行一个文件夹，默认 INBOX。可在邮箱中为不同转发来源配置文件夹。</small></span><textarea v-model="forwardedSettings.folders" rows="3" required placeholder="INBOX"></textarea></label>
    <div class="imap-security-note">授权码会先通过 IMAP 验证，然后用 AES-GCM 加密后保存到 D1。同步使用 BODY.PEEK 读取，不会修改远程已读状态。</div>
    <button class="button primary" :disabled="busy">{{ busy?'正在验证并保存…':'验证连接并保存' }}</button>
  </form>
</section><div class="settings-grid"><form class="card settings-card" @submit.prevent="savePreferences"><h2>使用偏好</h2><label class="setting-row"><span><strong>默认邮箱有效期</strong><small>创建临时邮箱时使用的时长。</small></span><select v-model.number="preferences.ttl"><option :value="10">10 分钟</option><option :value="30">30 分钟</option><option :value="60">60 分钟</option><option :value="1440">24 小时</option></select></label><label class="setting-row"><span><strong>收件箱刷新间隔</strong><small>定时刷新列表，不会主动触发 Gmail 同步。</small></span><select v-model.number="preferences.refreshSeconds"><option :value="15">15 秒</option><option :value="20">20 秒</option><option :value="30">30 秒</option><option :value="60">60 秒</option></select></label><label class="setting-row"><span><strong>默认遮挡验证码</strong><small>打开邮件时先隐藏识别出的验证码。</small></span><input v-model="preferences.maskOtp" type="checkbox"></label><label class="setting-row"><span><strong>界面主题</strong><small>选择工作台的阅读主题。</small></span><select v-model="preferences.theme"><option value="light">浅色</option><option value="dark">深色</option></select></label><button class="button primary save-button" type="submit">保存设置</button></form><section class="card privacy-card"><h2>隐私与安全</h2><p>邮件内容与附件由 MailHub 服务端通过你的 Cloudflare 资源存储。</p><div class="key-value"><span>Gmail 原邮件</span><b>只读访问</b></div><div class="key-value"><span>已读状态</span><b>MailHub 本地状态</b></div><div class="key-value"><span>邮件 HTML</span><b>隔离显示</b></div><div class="key-value"><span>附件病毒扫描</span><b>未提供</b></div></section></div></template>
    </main>
  </div>
</template>
